/**
 * The GUI's only door to the host.
 *
 * Everything that talks to the Rust side goes through here: the typed
 * `commands`, the `events` listeners and every contract type, generated by
 * tauri-specta into `src/bindings.ts`. Nothing else may import that file
 * (ESLint enforces it), which is what lets tests replace this one module with
 * a mock.
 */

import type { UnlistenFn } from "@tauri-apps/api/event";
import { events as generated } from "../bindings";

export { commands } from "../bindings";
export type {
  AppTag,
  AppUsage,
  AppsStatus,
  AppsUpdated,
  Category,
  CategoryUsage,
  ChangedBucket,
  CommandError,
  Connected,
  ConnectionLost,
  CopyProgress,
  CopyResult,
  Crumb,
  DeleteFailure,
  DeletedMany,
  Device,
  DeviceState,
  EntryKind,
  ErrorCode,
  FocusState,
  KindFilter,
  Leftover,
  Leftovers,
  Measure,
  NodeRef,
  Overview,
  Row,
  ScanFinished,
  ScanOutcome,
  ScanPhase,
  ScanProgress,
  ScanRecord,
  ScanStarted,
  SearchFilter,
  SearchRequest,
  SinceLastScan,
  Size,
  SizeMetric,
  SkeletonReady,
  SortKey,
  StagedChanged,
  StagedItem,
  StagedSummary,
  StagedTotals,
  Totals,
  TreemapNode,
  UnreadableFolder,
  View,
  ViewFilter,
  ViewRequest,
  ViewSort,
} from "../bindings";

import type { CommandError, ErrorCode } from "../bindings";

type Listenable<T> = { listen: (callback: (event: { payload: T }) => void) => Promise<UnlistenFn> };

/** An event as a function of its handler, which gets the payload alone. */
function onPayload<T>(event: Listenable<T>) {
  return (handler: (payload: T) => void): Promise<UnlistenFn> =>
    event.listen((e) => handler(e.payload));
}

/** Every host event. Each resolves to a function that stops listening. */
export const events = {
  scanProgress: onPayload(generated.scanProgress),
  copyProgress: onPayload(generated.copyProgress),
  connectionLost: onPayload(generated.connectionLost),
  appsUpdated: onPayload(generated.appsUpdated),
  stagedChanged: onPayload(generated.stagedChanged),
};

export function isCommandError(err: unknown): err is CommandError {
  return (
    typeof err === "object" &&
    err !== null &&
    typeof (err as CommandError).code === "string" &&
    typeof (err as CommandError).message === "string"
  );
}

/** The contract's error code, or null for anything that is not a `CommandError`. */
export function errorCode(err: unknown): ErrorCode | null {
  return isCommandError(err) ? err.code : null;
}

/** Text to show a person for whatever a command rejected with. */
export function errorMessage(err: unknown): string {
  if (isCommandError(err)) return err.message;
  if (typeof err === "string") return err;
  if (err instanceof Error) return err.message;
  return String(err);
}
